/bin/bash -lc "node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { createWorkspace } from './src/workspace.js';
import { createDraftStore } from './src/draft-store.js';
import { createReceiptArchive } from './src/receipt-archive.js';
let now = 0, next = 0;
const jobs = new Map();
const timers = { schedule(fn, delay) { const id = ++next; jobs.set(id, { fn, at: now + delay }); return id; }, cancel(id) { jobs.delete(id); } };
function advance(ms) { now += ms; for (;;) { const due = [...jobs].find(([, job]) => job.at <= now); if ("'!due) break; jobs.delete(due[0]); due[1].fn(); } }
const store = createDraftStore();
const archive = createReceiptArchive();
const writes = [];
store.subscribe(event => writes.push(event));
let document;
let notice;
const ws = createWorkspace({ store, archive, timers, renderDocument: value => document = value, renderStatus() {}, renderSubmission: value => notice = value });
ws.open('"'a'); ws.edit('a'); advance(60); ws.edit('ab'); advance(119);
assert.equal(writes.length, 0); advance(1);
assert.deepEqual(writes.map(x => x.text), ['ab']);
ws.edit('abc'); advance(120);
assert.deepEqual(writes.map(x => x.text), ['ab', 'abc']);
ws.edit('abcd'); ws.close();
assert.equal(store.read('a'), 'abcd'); assert.equal(jobs.size, 0);
ws.open('a'); assert.equal(document.text, 'abcd');
ws.edit('submit'); const receipt = ws.submit();
assert.deepEqual(receipt, { id: 'a', text: 'submit' });
assert.equal(store.read('a'), 'submit'); assert.equal(notice, receipt);
assert.equal(jobs.size, 0);
ws.edit('later'); advance(120); assert.equal(store.read('a'), 'later');
ws.dispose();
console.log('ok');
EOF"

